using System;
using System.Collections;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;
public sealed class B05Verifier:N5Runner
{
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Init()=>N5Args.Start<B05Verifier>("-verify-b05");
 protected override IEnumerator Tests(){yield return NewGame();Check(SceneManager.GetActiveScene().name=="A01_V2","V2 New Game mapping");var ids=new[]{"A01","A02","A03","A04","A05","A06","B01","B02","B03","B04","B05","B06","C01","C02","C03","C04","C05","C06"};foreach(var id in ids){if(N5Args.Value("-b05-room",id)!=id)continue;if(RoomSession.Instance.CurrentRoomId!=id){Check(RoomSession.Instance.RequestTransition(id,"Assets/Scenes/V2/"+id+"_V2.unity",id=="C06"?"FromLeft":"Entry"),"independent fixture "+id);yield return Ready();}if(id.StartsWith("B")||id.StartsWith("C"))RoomSession.Instance.GrantDash();if(id.StartsWith("C")||id=="B05")RoomSession.Instance.GrantDoubleJump();yield return Keys();yield return new WaitForSeconds(.3f);var colliders=FindObjectsByType<Collider2D>(FindObjectsSortMode.None);foreach(var c in colliders.Where(c=>!c.isTrigger))lines.Add("MEASURE "+id+" collision "+c.name+" center="+c.bounds.center+" size="+c.bounds.size);Check(FindObjectsByType<DiscoveryReward>(FindObjectsSortMode.None).Length==1,id+" exactly one discovery");var exits=FindObjectsByType<RoomExit>(FindObjectsSortMode.None);var exit=exits.FirstOrDefault(e=>e.destinationRoomId== (id=="B05"?"C01":id.Substring(0,1)+(int.Parse(id.Substring(1))+1).ToString("D2")))??exits.First();float goal=exit.transform.position.x;var input=gameObject.AddComponent<N9PogoInput>();input.keyboard=keyboard;var route=new RouteSegment{id="V2-MAIN-"+id,startScene=id+"_V2",goal=exit.destinationRoomId,startPosition=Body.position,dash=Player.GetComponent<PlayerDash>().hasDash,doubleJump=Motor.hasDoubleJump,startHP=Health.HP,limitSeconds=35};int tick=0,prior=0;var navigator=new B05Navigator();input.produce=()=>{tick++;if(!id.StartsWith("A")){var v=navigator.Generate(Player,exit.destinationRoomId,tick);v.tick=tick-1;v.pressed=v.held&~prior;v.released=prior&~v.held;prior=v.held;route.inputs.Add(v);var k=new System.Collections.Generic.List<Key>();if(v.axis>0)k.Add(Key.RightArrow);if(v.axis<0)k.Add(Key.LeftArrow);if((v.held&2)!=0)k.Add(Key.Z);if((v.held&8)!=0)k.Add(Key.X);return k.ToArray();}var keys=new System.Collections.Generic.List<Key>();keys.Add(goal>Body.position.x?Key.RightArrow:Key.LeftArrow);if(tick%50<26&&(id!="A03"||Body.position.x<27))keys.Add(Key.Z);if(id=="A04"&&tick%22==0)keys.Add(Key.X);int held=(keys.Contains(Key.Z)?2:0)|(keys.Contains(Key.X)?8:0);route.inputs.Add(new N5InputTick{tick=tick-1,axis=goal>Body.position.x?1:-1,held=held,pressed=held&~prior,released=prior&~held});prior=held;return keys.ToArray();};double end=Time.realtimeSinceStartupAsDouble+35;while(RoomSession.Instance.CurrentRoomId==id&&!RoomSession.Instance.Respawning&&Time.realtimeSinceStartupAsDouble<end)yield return null;input.produce=null;Destroy(input);yield return Keys();route.passed=!RoomSession.Instance.Respawning&&RoomSession.Instance.CurrentRoomId==exit.destinationRoomId;route.result=route.passed?"PASS":"FAIL";var library=new RouteLibrary();library.segments.Add(route);File.WriteAllText(Path.ChangeExtension(Evidence,id+"-main.inputs.json"),JsonUtility.ToJson(library,true));Check(!RoomSession.Instance.Respawning&&RoomSession.Instance.CurrentRoomId==exit.destinationRoomId,id+" entry to exit via virtual input pos="+Body.position);yield return Ready();}
 }
}



